import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-id'];
  // In production this comes from verified JWT claims
  req.tenantId = token || 'default';
  next();
}

app.use(extractTenant);

// Search endpoint with dynamic filtering
app.get('/api/v2/reports/search', async (req, res) => {
  try {
    const { category, date_from, date_to, sort_field, sort_dir } = req.query;
    const tenantId = req.tenantId;

    // Base query with tenant isolation
    let query = `SELECT id, title, category, created_at, summary 
                 FROM reports WHERE tenant_id = $1`;
    let params = [tenantId];
    let paramIdx = 2;

    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (date_from) {
      query += ` AND created_at >= $${paramIdx}`;
      params.push(date_from);
      paramIdx++;
    }

    if (date_to) {
      query += ` AND created_at <= $${paramIdx}`;
      params.push(date_to);
      paramIdx++;
    }

    // Sort - validated against allowlist... or so we think
    const allowedSorts = ['created_at', 'title', 'category', 'id'];
    const direction = sort_dir === 'desc' ? 'DESC' : 'ASC';

    if (sort_field) {
      // Developer intended to validate but used includes() on string
      // which matches substrings: 'id' matches 'tenant_id', etc.
      if (allowedSorts.some(f => sort_field.includes(f))) {
        query += ` ORDER BY ${sort_field} ${direction}`;
      } else {
        query += ` ORDER BY created_at ${direction}`;
      }
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    query += ` LIMIT 50`;

    const result = await pool.query(query, params);
    res.json({ data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/reports/export', async (req, res) => {
  try {
    const { ids, format } = req.body;
    const tenantId = req.tenantId;

    if (!Array.isArray(ids) || ids.length === 0 || ids.length > 100) {
      return res.status(400).json({ error: 'Invalid ids array' });
    }

    const placeholders = ids.map((_, i) => `$${i + 2}`).join(',');
    const query = `SELECT * FROM reports WHERE tenant_id = $1 AND id IN (${placeholders})`;
    const result = await pool.query(query, [tenantId, ...ids]);

    const exportId = crypto.randomUUID();
    res.json({ export_id: exportId, records: result.rowCount });
  } catch (err) {
    res.status(500).json({ error: 'Export failed' });
  }
});

// Health check
app.get('/healthz', (req, res) => res.json({ status: 'ok' }));

app.listen(parseInt(process.env.PORT || '3000'), '0.0.0.0');
